function testo(v) { return v === null || v === undefined ? '' : String(v).trim(); }
function norm(v) { return testo(v).toLowerCase(); }
function senzaAccenti(s) { return String(s).normalize('NFD').replace(/[̀-ͯ]/g, ''); }
