  const diretti = voci.filter((f) => !eCartella(f)).map((f) => ({ id: f.id, name: f.name, mimeType: f.mimeType, createdTime: f.createdTime }));
  // un servizio è una cartella con le sottocartelle del servizio (video verticali, video orizzontali, foto…): una cartella
  // qualunque («Grafiche», «Menu») non fa partire niente. I servizi con i file sciolti si lanciano dal modulo.
  if (!cartelle.length) return;
  cartelle.forEach((f, k) => out.push({ json: { ...s, cartella: f.id, diretti: k === 0 ? diretti : [] } }));
});
return out;

// ===== Aiuti comuni del workflow 16 · Montatore (blocco uguale in tutti i nodi Code: si modifica qui e si rigenera) =====
// (Snellito: qui restano solo gli aiuti che questo nodo usa; tolti 39.)
const CARTELLA_MIME = 'application/vnd.google-apps.folder';
const ESTENSIONI_VIDEO = ['mp4', 'mov', 'm4v', 'avi', 'mkv', 'webm', 'mts', 'm2ts', '3gp', 'hevc', 'mpg', 'mpeg'];
const ESTENSIONI_FOTO = ['jpg', 'jpeg', 'png', 'webp', 'tif', 'tiff', 'avif'];
const ESTENSIONI_AUDIO = ['mp3', 'm4a', 'wav', 'aac', 'ogg', 'oga', 'flac', 'opus'];

function testo(v) { return v === null || v === undefined ? '' : String(v).trim(); }
function intero(v, predefinito) { const n = parseInt(v, 10); return Number.isFinite(n) ? n : predefinito; }
// Testo sicuro per Telegram in modalità HTML.
function h(v) { return String(v === null || v === undefined ? '' : v).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); }

// Google Drive: id da un link o da un id nudo.
function idDrive(v) {
  const s = testo(v);
  const m = s.match(/\/d\/([A-Za-z0-9_-]{10,})/) || s.match(/[?&]id=([A-Za-z0-9_-]{10,})/) || s.match(/\/folders\/([A-Za-z0-9_-]{10,})/);
  if (m) return m[1];
  if (/^[A-Za-z0-9_-]{20,}$/.test(s)) return s;
  return '';
}
function linkCartella(id) { return 'https://drive.google.com/drive/folders/' + id; }
function estensione(nome) { const m = testo(nome).toLowerCase().match(/\.([a-z0-9]{1,5})$/); return m ? m[1] : ''; }
function eCartella(f) { return !!f && f.mimeType === CARTELLA_MIME; }
function eVideo(f) { return !eCartella(f) && (/^video\//i.test(testo(f.mimeType)) || ESTENSIONI_VIDEO.includes(estensione(f.name))); }
function eFoto(f) { return !eCartella(f) && !/heic|heif/i.test(testo(f.mimeType) + estensione(f.name)) && (/^image\/(jpeg|png|webp|tiff|avif)/i.test(testo(f.mimeType)) || ESTENSIONI_FOTO.includes(estensione(f.name))); }
function eAudio(f) { return !eCartella(f) && (/^audio\//i.test(testo(f.mimeType)) || ESTENSIONI_AUDIO.includes(estensione(f.name))); }
function logoDi(v) {
  const s = testo(v);
  if (!s) return { tipo: 'nessuno', id: '', url: '' };
  const daDrive = /^https?:\/\/(drive|docs)\.google\.com\//i.test(s) || /^[A-Za-z0-9_-]{20,}$/.test(s);
  if (daDrive && idDrive(s)) return { tipo: 'drive', id: idDrive(s), url: '' };
  if (/^https:\/\/[^\s"'<>]+$/i.test(s)) return { tipo: 'url', id: '', url: s };
  return { tipo: 'nessuno', id: '', url: '' };
}
// Un indirizzo dell'officina (assoluto o relativo) → il percorso dopo /file/, da mettere dietro OFFICINA_URL.
function percorsoOfficina(url) { return String(url || '').replace(/^.*?(^|\/)file\//, ''); }
// Telegram con i pulsanti (sendAndWait) usa il Markdown semplice: si neutralizzano _ * ` [ (come nel workflow 15).
function md(v) { return String(v === null || v === undefined ? '' : v).replace(/\\/g, '/').replace(/([_*`[])/g, '\\$1'); }
// ===== fine aiuti comuni =====

// ===== guarda-pronti.js =====
// (guardiano delle cartelle) Un servizio è pronto quando ha del materiale e nessun file nuovo da QUIETE_MINUTI
// (la copia dalla scheda SD è finita). Allora parte il montaggio, una volta sola per cartella (il mese lo decide «Prepara il lavoro»).
const J = $('Config').first().json;
const S = $getWorkflowStaticData('global');
S.servizi = S.servizi || {};
const quiete = Math.max(5, intero(J.QUIETE_MINUTI, 30)) * 60000;
const ora = Date.now();
const dove = $('Guarda: sottocartelle').all().map((x) => x.json);
const per = new Map();
$input.all().forEach((x, i) => {
  const s = dove[i];
  if (!s) return;
  const e = per.get(s.servizio_id) || { s, file: new Map(), errori: 0 };
  if (!x.json || x.json.error) e.errori++;
  for (const f of [...((x.json && x.json.files) || []), ...(s.diretti || [])]) e.file.set(f.id, f);
  per.set(s.servizio_id, e);
});
const out = [];
for (const [id, e] of per) {
  if (e.errori) continue; // Drive non ha risposto: si riguarda al prossimo giro
  // conta solo il materiale che si monta: una cartella con sola musica o sole HEIC non «consuma» la partenza
  const materiale = [...e.file.values()].filter((f) => eVideo(f) || eFoto(f));
  if (!materiale.length) continue;
  const ultimo = Math.max(...materiale.map((f) => Date.parse(f.createdTime) || 0));
  if (ora - ultimo < quiete) continue; // si sta ancora copiando
  S.servizi[id] = { ...(S.servizi[id] || {}), avviato: new Date(ora).toISOString() };
  out.push({ json: {
    lavoro: 'avvia',
    origine: 'cartella',
    cliente: e.s.cliente,
    cartella: linkCartella(id),
    servizio_nome: e.s.servizio_nome,
    // mese e quantità vuoti: li decide «Prepara il lavoro» (regola del giorno limite, pacchetto del cliente)
    mese: '',
    reel: '',
    post: '',
    storie: '',
    note: '',
    messaggio: '👀 <b>Servizio nuovo</b> · ' + h(e.s.nome_locale) + ' · «' + h(e.s.servizio_nome) + '»\n' + materiale.length + ' file, l\'ultimo caricato ' + Math.round((ora - ultimo) / 60000) + ' minuti fa: parto da solo con il piano del mese (quello in corso fino al giorno ' + intero(J.GIORNO_LIMITE_MESE, 10) + ', poi il successivo).',
  } });
}
return out;
